import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { logo } from "../assets/home";
import Container from "./Container";
import "./Navbar.css";

function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  // Detect scroll for shrinking navbar
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav
      className={`navbar-container ${
        scrolled ? "navbar-scrolled" : ""
      } fixed top-0 left-0 w-full z-50`}
    >
      <Container>
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-3">
            <img src={logo} alt="Live Hunt Share" className="h-10 w-auto logo-img" />
          </Link>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-8">
            {["Home", "Funding", "About", "Membership", "Contact"].map((item, idx) => (
              <Link key={idx} to="/" className="nav-link">
                {item}
              </Link>
            ))}
          </div>

          {/* Login Button */}
          <Link to="/" className="hidden md:block">
            <div className="login-btn">Log In</div>
          </Link>

          {/* Hamburger Button */}
          <div className="md:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`hamburger ${isOpen ? "open" : ""}`}
            >
              <span></span>
              <span></span>
              <span></span>
            </button>
          </div>
        </div>
      </Container>

      {/* Mobile Menu */}
      <div className={`mobile-menu ${isOpen ? "open" : ""}`}>
        <div className="mobile-menu-inner">
          {["Home", "Funding", "About", "Membership", "Contact"].map((item, idx) => (
            <Link
              key={idx}
              to="/"
              className="mobile-link"
              onClick={() => setIsOpen(false)}
            >
              {item}
            </Link>
          ))}
          <Link to="/" className="login-btn w-full text-center mt-6" onClick={() => setIsOpen(false)}>
            Log In
          </Link>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
